using namespace std;

const int MAXN = 300;
const int INF = 1e9;

struct FlowEdge {
    int to, rev, flow, capacity;
    FlowEdge(int to, int rev, int flow, int capacity) : to(to), rev(rev), flow(flow), capacity(capacity) {}
};
vector<FlowEdge> network[MAXN];

void connectNodes(int u, int v, int c, int rc = 0) {
    FlowEdge e1(v, network[v].size(), 0, c);
    FlowEdge e2(u, network[u].size(), 0, rc);
    network[u].push_back(e1);
    network[v].push_back(e2);
}

int distArr[MAXN], ptrArr[MAXN], start, end;

bool buildLevelGraph() {
    memset(distArr, -1, sizeof(distArr));
    distArr[start] = 0;
    queue<int> q({start});
    while (!q.empty() && distArr[end] == -1) {
        int u = q.front(); q.pop();
        for (auto &edge : network[u]) {
            int v = edge.to;
            if (distArr[v] == -1 && edge.flow < edge.capacity) {
                distArr[v] = distArr[u] + 1;
                q.push(v);
            }
        }
    }
    return distArr[end] != -1;
}

int sendFlow(int u, int flow) {
    if (u == end || flow == 0)
        return flow;
    for (int &i = ptrArr[u]; i < network[u].size(); i++) {
        auto &e = network[u][i];
        int v = e.to;
        if (distArr[v] != distArr[u] + 1)
            continue;
        if (int pushed = sendFlow(v, min(flow, e.capacity - e.flow))) {
            e.flow += pushed;
            network[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int computeFlow() {
    int total = 0;
    while (buildLevelGraph()) {
        memset(ptrArr, 0, sizeof(ptrArr));
        while (int pushed = sendFlow(start, INT_MAX))
            total += pushed;
    }
    return total;
}

int deltaX[] = {-1, 0, 0, 1};
int deltaY[] = {0, -1, 1, 0};

int n, m;
using Grid = vector<vector<int>>;
using Point = array<int, 2>;
Grid obs, distT, distD;

void runBFS(int r, int c, Grid &dis, bool check = false) {
    for (int i = 0; i < n; i++)
        fill(dis[i].begin(), dis[i].end(), -1);
