import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int INF = (int)1e9;

    static class FlowEdge {
        int to, rev, flow, capacity;
        FlowEdge(int to, int rev, int flow, int capacity) {
            this.to = to;
            this.rev = rev;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static List<FlowEdge>[] network = new ArrayList[MAXN];
    static int[] distArr = new int[MAXN];
    static int[] ptrArr = new int[MAXN];
    static int start, end;
    static int n, m;
    static List<String> lab = new ArrayList<>();
    static List<String> rea = new ArrayList<>();
    static int[][] obs, distT, distD;

    static int[] deltaX = {-1, 0, 0, 1};
    static int[] deltaY = {0, -1, 1, 0};

    static void connectNodes(int u, int v, int c, int rc) {
        network[u].add(new FlowEdge(v, network[v].size(), 0, c));
        network[v].add(new FlowEdge(u, network[u].size() - 1, 0, rc));
    }

    static boolean buildLevelGraph() {
        Arrays.fill(distArr, -1);
        distArr[start] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        while (!q.isEmpty() && distArr[end] == -1) {
            int u = q.poll();
            for (FlowEdge e : network[u]) {
                int v = e.to;
                if (distArr[v] == -1 && e.flow < e.capacity) {
                    distArr[v] = distArr[u] + 1;
                    q.offer(v);
                }
            }
        }
        return distArr[end] != -1;
    }

    static int sendFlow(int u, int flow) {
        if (u == end || flow == 0)
            return flow;
        for (; ptrArr[u] < network[u].size(); ptrArr[u]++) {
            FlowEdge e = network[u].get(ptrArr[u]);
            int v = e.to;
            if (distArr[v] != distArr[u] + 1)
                continue;
            int pushed = sendFlow(v, Math.min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                network[v].get(e.rev).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int computeFlow() {
        int total = 0;
        while (buildLevelGraph()) {
            Arrays.fill(ptrArr, 0);
            int pushed;
            while ((pushed = sendFlow(start, Integer.MAX_VALUE)) > 0) {
                total += pushed;
            }
        }
        return total;
    }

    static void runBFS(int r, int c, int[][] dis, boolean check) {
        for (int i = 0; i < n; i++)
            Arrays.fill(dis[i], -1);
        dis[r][c] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{r, c});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pr = p[0], pc = p[1];
            if (check && dis[pr][pc] == distT[pr][pc])
                continue;
            for (int i = 0; i < 4; i++) {
                int nr = pr + deltaX[i];
                int nc = pc + deltaY[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || dis[nr][nc] != -1 || obs[nr][nc] == 1)
                    continue;
                if (check && distT[nr][nc] > -1 && dis[pr][pc] + 1 > distT[nr][nc])
                    continue;
                dis[nr][nc] = dis[pr][pc] + 1;
                q.offer(new int[]{nr, nc});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXN; i++) {
            network[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            lab.add(br.readLine());
        }
        for (int i = 0; i < n; i++) {
            rea.add(br.readLine());
        }

        obs = new int[n][n];
        distT = new int[n][n];
        distD = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                obs[i][j] = (lab.get(i).charAt(j) == 'Y') ? 1 : 0;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (lab.get(i).charAt(j) == 'Z') {
                    runBFS(i, j, distT, false);
                }
            }
        }

        start = 2 * n * n + 5;
        end = start + 1;

        for (int i = 0; i < MAXN; i++) {
            network[i].clear();
        }

        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (lab.get(x).charAt(y) == 'Z' || lab.get(x).charAt(y) == 'Y')
                    continue;
                connectNodes(start, n * x + y, lab.get(x).charAt(y) - '0', 0);
                connectNodes(n * n + n * x + y, end, rea.get(x).charAt(y) - '0', 0);
                runBFS(x, y, distD, true);
                for (int xp = 0; xp < n; xp++) {
                    for (int yp = 0; yp < n; yp++) {
                        if (distD[xp][yp] != -1 && distD[xp][yp] <= m) {
                            connectNodes(n * x + y, n * n + n * xp + yp, INF, 0);
                        }
                    }
                }
            }
        }

        System.out.println(computeFlow());
    }
}
